class NonDataLabel:
    def __get__(self, instance, owner):
        return 'computed' if instance is not None else self

class DataPercent:
    def __get__(self, instance, owner):
        return instance._percent if instance is not None else self

    def __set__(self, instance, value):
        if type(value) is not int or not 0 <= value <= 100:
            raise ValueError('percent must be 0..100')
        instance._percent = value

class Progress:
    label = NonDataLabel()
    percent = DataPercent()

    def __init__(self):
        self.percent = 25

item = Progress()
item.__dict__['label'] = 'instance label'
item.__dict__['percent'] = 999
print(item.label)
print(item.percent)
print(isinstance(Progress.label, NonDataLabel))
